import{createLogger}from"#internal/logging.js";import{SessionIdKey}from"#context/keys.js";import{sandboxPrewarmer}from"#context/providers/sandbox.js";const log=createLogger(`context.prewarm`),sessionPrewarmers=[sandboxPrewarmer];function startSessionPrewarmers(e,t){for(let n of sessionPrewarmers)try{n.start(e,t)}catch(r){log.warn(`session prewarmer failed to start; its work runs when needed`,{error:r,phase:t,prewarmer:n.name,sessionId:e.get(SessionIdKey)})}}export{startSessionPrewarmers};